import{_ as e,o as a,c as r,a5 as i}from"./chunks/framework.BZzouRtU.js";const o="/study/images/game/collisions-and-physics.svg",y=JSON.parse('{"title":"衝突と物理の基本 — コライダー・Rigidbody・トリガー","description":"","frontmatter":{"title":"衝突と物理の基本 — コライダー・Rigidbody・トリガー","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"描画用の形と当たり判定の形を分け、接触の検出、物理の応答、ゲームのルールへつなぐ。Unityの3D物理を例に、Rigidbody、トリガー、すり抜け、レイの検査を説明する。","aliases":["衝突","当たり判定","collision","Collider","コライダー","Rigidbody","剛体","静的","動的","kinematic","キネマティック","trigger","トリガー","CCD","レイキャスト"],"verification":"Unity 6.0の3D Collider・Rigidbody・イベント・CCD・Raycastの公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/collisions-and-physics.md","filePath":"game/basics/collisions-and-physics.md"}'),n={name:"game/basics/collisions-and-physics.md"};function s(d,t,l,c,h,g){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="衝突と物理の基本-—-コライダー・rigidbody・トリガー" tabindex="-1">衝突と物理の基本 — コライダー・Rigidbody・トリガー <a class="header-anchor" href="#衝突と物理の基本-—-コライダー・rigidbody・トリガー" aria-label="Permalink to &quot;衝突と物理の基本 — コライダー・Rigidbody・トリガー&quot;">​</a></h1><p>ゲームの弾が敵に触れる、箱が床へ落ちる、入口へ入ると次の場面へ進む。どれも空間での接触や重なりを使いますが、その後に起こしたい処理は違います。ここでは<strong>Unity 6.0の3D物理</strong>を例に、形を用意して結果を使うまでを見ます。Unityの2D物理は、別のコンポーネントとシミュレーションを使います。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/CollidersOverview.html" target="_blank" rel="noreferrer">Unityの衝突の基本</a></p><h2 id="見える形と、接触を調べる形" tabindex="-1">見える形と、接触を調べる形 <a class="header-anchor" href="#見える形と、接触を調べる形" aria-label="Permalink to &quot;見える形と、接触を調べる形&quot;">​</a></h2><p><strong>メッシュ</strong>は、頂点や面からなる描画用の形です。**コライダー（Collider）**は、当たり判定に使う形です。人型キャラクターにカプセル形のコライダーを付けるなど、見た目より単純な形を使えます。球、箱、カプセルなどの形を組み合わせる方法もあります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/CollidersOverview.html" target="_blank" rel="noreferrer">Unityのコライダーの形</a> · <a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a></p><p><strong>衝突判定</strong>は、形同士が接触したり重なったりしたかを調べます。<strong>物理シミュレーション</strong>は、速度や力、接触などをもとに、次の位置や動きを計算します。重なりをゲームへ知らせるだけの使い方も、物理計算で箱を跳ね返す使い方もあります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/collider-types-interaction.html" target="_blank" rel="noreferrer">Unityの衝突の扱い</a></p><figure class="study-figure"><img src="'+o+'" alt="同じ物の見た目をメッシュで描き、当たり判定を単純な箱のコライダーで表す。接触を調べた結果は、物理の応答で箱の動きを変えたり、ゲームの処理へ渡してHPを減らしたりするために使う。" width="760" height="470" loading="lazy"><figcaption>接触の検出から、物理の動きとゲーム固有のルールへつなぎます。<a href="/study/images/game/collisions-and-physics.svg" target="_blank" rel="noopener noreferrer">衝突と応答の図を拡大</a></figcaption></figure><h2 id="rigidbodyで動きを扱う" tabindex="-1">Rigidbodyで動きを扱う <a class="header-anchor" href="#rigidbodyで動きを扱う" aria-label="Permalink to &quot;Rigidbodyで動きを扱う&quot;">​</a></h2><p><strong>Rigidbody</strong>（剛体）は、質量や速度などを持ち、物理計算で扱う物体のまとまりです。Unityの3D物理では、ColliderとRigidbodyの組み合わせによって使い方が変わります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Rigidbody.html" target="_blank" rel="noreferrer">UnityのRigidbody</a></p><table tabindex="0"><thead><tr><th>種類</th><th>Unityでの基本構成</th><th>使う場面</th></tr></thead><tbody><tr><td><strong>静的（Static）</strong></td><td>Colliderがあり、Rigidbodyがない。</td><td>動かさない床や壁。</td></tr><tr><td><strong>動的（Dynamic）</strong></td><td>ColliderとRigidbodyがあり、Is Kinematicがオフ。</td><td>重力で落ち、接触で動きが変わる箱。</td></tr><tr><td><strong>キネマティック（Kinematic）</strong></td><td>ColliderとRigidbodyがあり、Is Kinematicがオン。</td><td>スクリプトやアニメーションが動きを決める足場など。</td></tr></tbody></table><p>動的な物体には力や重力を使い、物理計算に移動を任せられます。キネマティックな物体は、外から指定する動きを使いながら、対応する相手との物理的なやり取りに参加します。用途に合う構成を選び、物理が扱う位置を更新するAPIも確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/CollidersOverview.html" target="_blank" rel="noreferrer">UnityのColliderの種類</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-Rigidbody.html" target="_blank" rel="noreferrer">Rigidbodyの設定</a></p><h2 id="トリガーで重なりを知らせる" tabindex="-1">トリガーで重なりを知らせる <a class="header-anchor" href="#トリガーで重なりを知らせる" aria-label="Permalink to &quot;トリガーで重なりを知らせる&quot;">​</a></h2><p><strong>トリガー</strong>は、相手を押し返す衝突応答を行わず、重なりを知らせるコライダーです。入口の領域やアイテムの取得範囲に使えます。UnityではColliderの<strong>Is Trigger</strong>を有効にし、<code>OnTriggerEnter</code>などで通知を受け取ります。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Collider.OnTriggerEnter.html" target="_blank" rel="noreferrer">Unityのトリガーイベント</a></p><p>Unityの3Dトリガーでは、組のうち少なくとも片方にRigidbodyが必要です。キネマティックなRigidbodyでも対象になります。一方、通常の<code>OnCollision</code>の通知は、少なくとも片方が動的なColliderの組で発生します。通知の有無は、Colliderの組み合わせや、レイヤーの衝突設定も含めて確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/collider-types-interaction.html" target="_blank" rel="noreferrer">UnityのColliderの組み合わせ</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/Manual/LayerBasedCollision.html" target="_blank" rel="noreferrer">レイヤーによる衝突の選別</a></p><h2 id="「触れた」からゲームのルールへ" tabindex="-1">「触れた」からゲームのルールへ <a class="header-anchor" href="#「触れた」からゲームのルールへ" aria-label="Permalink to &quot;「触れた」からゲームのルールへ&quot;">​</a></h2><p>弾と敵の接触を通知されたら、ゲーム側が相手を調べ、HPを減らし、弾を消すなどの処理を決めます。物理エンジンが扱う接触と、「敵に30ダメージ」というルールを結び付けるのがゲームのコードです。複数のコライダーや継続する接触から通知を受ける設計では、一発の攻撃を何度適用するかも決めます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/collider-types-interaction.html" target="_blank" rel="noreferrer">Unityの接触イベント</a> · <a href="/study/game/shooter-design.html">シューティングの設計</a></p><h2 id="速い物体は、途中を通り過ぎることがある" tabindex="-1">速い物体は、途中を通り過ぎることがある <a class="header-anchor" href="#速い物体は、途中を通り過ぎることがある" aria-label="Permalink to &quot;速い物体は、途中を通り過ぎることがある&quot;">​</a></h2><p>物理は時間を区切った<strong>ステップ</strong>で進みます。位置を区切りごとに調べる<strong>離散的な衝突判定</strong>では、速い小さな弾が、前の位置と次の位置の間にある薄い壁を通り過ぎる場合があります。**CCD（連続衝突判定）**は、その間の移動も考慮して、すり抜けを減らすための仕組みです。対象の形や動きに応じて方式を選び、実際の速度で確かめます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/ContinuousCollisionDetection.html" target="_blank" rel="noreferrer">UnityのCCD</a> · <a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a></p><p><strong>レイキャスト</strong>は、始点からある方向へ線を伸ばし、設定した距離内でどのコライダーに当たるかを調べる問い合わせです。地面の位置、照準、遮られているかの確認などに使えます。太さを持つ物体の移動を調べたい場合は、球などの形を使う問い合わせもあります。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Physics.Raycast.html" target="_blank" rel="noreferrer">UnityのPhysics.Raycast</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Physics.SphereCast.html" target="_blank" rel="noreferrer">Physics.SphereCast</a></p><p>部品の付け方と配置の関係は<a href="/study/game/basics/scenes-and-components.html">シーンとコンポーネント</a>、位置や大きさの基準は<a href="/study/graphics/basics/transforms-and-cameras.html">座標とカメラ</a>へ進みます。</p><p>物理ステップで位置を進め、形状の重なりを調べる計算は、<a href="/study/math/physics-integration-and-collision.html">物理の時間積分と衝突判定</a>で確認できます。</p>',20)])])}const u=e(n,[["render",s]]);export{y as __pageData,u as default};
